sp_widget.css:
.cp-stats { max-width:1120px; margin:0 auto; padding:24px 28px 8px;
  display:grid; grid-template-columns:repeat(4,1fr); gap:16px; }
.cp-tile { padding:20px 22px; position:relative; overflow:hidden; }
.cp-tile::before { content:""; position:absolute; left:0; top:0; bottom:0; width:4px; background:var(--cp-line); }
.cp-tile--gold::before { background:var(--cp-gold); }
.cp-tile--teal::before { background:var(--cp-teal); }
.cp-tile--danger::before { background:var(--cp-danger); }
.cp-tile--navy::before { background:var(--cp-navy); }
.cp-tile__value { font-size:34px; font-weight:850; letter-spacing:-.02em; }
.cp-tile__label { color:var(--cp-muted); font-size:13px; font-weight:700; margin-top:2px; }
@media (max-width:760px){ .cp-stats{ grid-template-columns:repeat(2,1fr); } }

sp_widget.script:
(function() {
  function count(states) {
    var gr = new GlideRecord('x_1970973_claim_0_insurance_claims');
    gr.addQuery('customer', gs.getUserID());
    if (states) gr.addQuery('state', 'IN', states);
    gr.query();
    return gr.getRowCount();
  }
  data.tiles = [
    { label:'Open',         value: count('1,2,3'), cls:'cp-tile--gold' },
    { label:'Approved',     value: count('4'),     cls:'cp-tile--teal' },
    { label:'Rejected',     value: count('5'),     cls:'cp-tile--danger' },
    { label:'Total claims', value: count(''),      cls:'cp-tile--navy' }
  ];
})();
